}
printStatusCode(404);
printStatusCode('404');
```

### Type Guards

```ts
function printStatusCode(code: string | number) {
  console.log(`My status code is ${code.toUpperCase()}.`)
  // error: Property 'toUpperCase' does not exist on type 'string | number'.
  // Property 'toUpperCase' does not exist on type 'number'
}
```

> [!NOTE]
> In our example we are having an issue invoking `toUpperCase()` as it's a string method and number doesn't have access to it.

## TypeScript Functions

- Reference material for [Functions](https://www.w3schools.com/typescript/typescript_functions.php)
- See [More on Functions](https://www.typescriptlang.org/docs/handbook/2/functions.html) for additional information

### Return Type

```ts
// the `: number` here specifies that this function returns a number
function getTime(): number {
  return new Date().getTime();
}
```

### Void Return Type

```ts
function printHello(): void {
  console.log('Hello!');
}
```

### Parameters

```ts
function multiply(a: number, b: number) {
  return a * b;
}
```

### Optional Parameters

```ts
// the `?` operator here marks parameter `c` as optional
function add(a: number, b: number, c?: number) {
  return a + b + (c || 0);
}
```

### Default Parameters

```ts
function pow(value: number, exponent: number = 10) {
  return value ** exponent;
}
```

### Named Parameters

```ts
function divide({ dividend, divisor }: { dividend: number, divisor: number }) {
  return dividend / divisor;
}
```

### Rest Parameters

```ts
function add(a: number, b: number, ...rest: number[]) {
  return a + b + rest.reduce((p, c) => p + c, 0);
}
```

### Type Alias

```ts
type Negate = (value: number) => number;

// in this function, the parameter `value` automatically gets assigned
// the type `number` from the type `Negate`
const negateFunction: Negate = (value) => value * -1;
```

