### Override

```ts
interface Shape {
  getArea: () => number;
}

class Rectangle implements Shape {
  // using protected for these members allows access from classes
  // that extend from this class, such as Square
  public constructor(
    protected readonly width: number,
    protected readonly height: number
  ) {}

  public getArea(): number {
    return this.width * this.height;
  }

  public toString(): string {
    return `Rectangle[width=${this.width}, height=${this.height}]`;
  }
}

class Square extends Rectangle {
  public constructor(width: number) {
    super(width, width);
  }

  // this toString replaces the toString from Rectangle
  public override toString(): string {
    return `Square[width=${this.width}]`;
  }
}
```

### Abstract Classes

```ts
abstract class Polygon {
  public abstract getArea(): number;

  public toString(): string {
    return `Polygon[area=${this.getArea()}]`;
  }
}

class Rectangle extends Polygon {
  public constructor(
    protected readonly width: number,
    protected readonly height: number
  ) {
    super();
  }

  public getArea(): number {
    return this.width * this.height;
  }
}
```
## TypeScript Basic Generics

- Reference [Basic Generics](https://www.w3schools.com/typescript/typescript_basic_generics.php)

### Functions

```ts
function createPair<S, T>(v1: S, v2: T): [S, T] {
  return [v1, v2];
}
console.log(createPair<string, number>('hello', 42)); // ['hello', 42]
```

### Classes

```ts
class NamedValue<T> {
  private _value: T | undefined;

  constructor(private name: string) {}

  public setValue(value: T) {
    this._value = value;
  }

  public getValue(): T | undefined {
    return this._value;
  }

  public toString(): string {
    return `${this.name}: ${this._value}`;
  }
}

let value = new NamedValue<number>('myNumber');
value.setValue(10);
console.log(value.toString()); // myNumber: 10
```

### Type Aliases

```ts
type Wrapped<T> = { value: T };

const wrappedValue: Wrapped<number> = { value: 10 };
```

### Default Value

```ts
class NamedValue<T = string> {
  private _value: T | undefined;

  constructor(private name: string) {}

  public setValue(value: T) {
    this._value = value;
  }

  public getValue(): T | undefined {
    return this._value;
  }

  public toString(): string {
    return `${this.name}: ${this._value}`;
  }
}

let value = new NamedValue('myNumber');
value.setValue('myValue');
console.log(value.toString()); // myNumber: myValue
```

### Extends Constraint

```ts
function createLoggedPair<S extends string | number, T extends string | number>(v1: S, v2: T): [S, T] {
  console.log(`creating pair: v1='${v1}', v2='${v2}'`);
  return [v1, v2];
}
```
## TypeScript Utility Types

- Reference [Utility Types](https://www.w3schools.com/typescript/typescript_utility_types.php)

### Partial

```ts
interface Point {
  x: number;
  y: number;
}

let pointPart: Partial<Point> = {}; // `Partial` allows x and y to be optional
pointPart.x = 10;
```

### Required

```ts
interface Car {
  make: string;
  model: string;
  mileage?: number;
}

let myCar: Required<Car> = {
  make: 'Ford',
  model: 'Focus',
  mileage: 12000 // `Required` forces mileage to be defined
};
```

### Record

```ts
const nameAgeMap: Record<string, number> = {
  'Alice': 21,
  'Bob': 25
};
```

### Omit

```ts
interface Person {
  name: string;
  age: number;
  location?: string;
}

const bob: Omit<Person, 'age' | 'location'> = {
  name: 'Bob'
  // `Omit` has removed age and location from the type and they can't be defined here
};
```

### Pick

```ts
interface Person {
  name: string;
  age: number;
  location?: string;
}

const bob: Pick<Person, 'name'> = {
  name: 'Bob'
  // `Pick` has only kept name, so age and location were removed
  // from the type and they can't be defined here
};
```

### Exclude

```ts
type Primitive = string | number | boolean
const value: Exclude<Primitive, string> = true;
// a string cannot be used here since Exclude removed it from the type.
```

### ReturnType

```ts
type PointGenerator = () => { x: number; y: number; };
const point: ReturnType<PointGenerator> = {
  x: 10,
  y: 20
};
```

### Parameters

```ts
type PointPrinter = (p: { x: number; y: number; }) => void;
const point: Parameters<PointPrinter>[0] = {
  x: 10,
  y: 20
};
```

### Readonly

```ts
interface Person {
  name: string;
  age: number;
}
const person: Readonly<Person> = {
  name: "Dylan",
  age: 35,
};
person.name = 'Israel';
// prog.ts(11,8): error TS2540: Cannot assign to 'name' because it is a
// read-only property.
```

# TypeScript d.ts Templates

Template patterns for TypeScript declaration files (.d.ts) from the official TypeScript documentation.

## Modules .d.ts

- Reference material for [Modules .d.ts](https://www.typescriptlang.org/docs/handbook/declaration-files/templates/module-d-ts.html)

Use this template when writing a declaration file for a module that is consumed via `import` or `require`. This is the most common template for npm packages.

### Determining What Kind of Module

Before writing a module declaration, look at the JavaScript source for clues:

- Uses `module.exports = ...` or `exports.foo = ...` — use `export =` syntax
- Uses `export default` or named `export` statements — use ES module syntax
- Both accessible as a global and via `require` — use `export as namespace` (UMD)

### Module Template

```ts
// Type definitions for [~THE LIBRARY NAME~] [~OPTIONAL VERSION NUMBER~]
// Project: [~THE PROJECT NAME~]
// Definitions by: [~YOUR NAME~] <[~A URL FOR YOU~]>

/*~ This is the module template file. You should rename it to index.d.ts
 *~ and place it in a folder with the same name as the module.
 *~ For example, if you were writing a file for "super-greeter", this
 *~ file should be 'super-greeter/index.d.ts'
 */

/*~ If this module is a UMD module that exposes a global variable 'myLib'
 *~ when loaded outside a module loader environment, declare that global here.
 *~ Remove this section if your library is not UMD.
 */
export as namespace myLib;

/*~ If this module exports functions, declare them like so.
 */
export function myFunction(a: string): string;
export function myOtherFunction(a: number): number;

/*~ You can declare types that are available via importing the module.
 */
export interface someType {
  name: string;
  length: number;
  extras?: string[];
}

/*~ You can declare properties of the module using const, let, or var.
 */
export const myField: number;

/*~ If there are types, properties, or methods inside dotted names in your
 *~ module, declare them inside a 'namespace'.
 */
export namespace subProp {
  /*~ For example, given this definition, someone could write:
   *~   import { subProp } from 'yourModule';
   *~   subProp.foo();
   *~   or
   *~   import * as yourModule from 'yourModule';
   *~   yourModule.subProp.foo();
   */
  export function foo(): void;
}
```

### Exporting a Class and Namespace Together

When the module exports a class as well as related types:

```ts
export = MyClass;

declare class MyClass {
  constructor(someParam?: string);
  someProperty: string[];
  myMethod(opts: MyClass.MyClassMethodOptions): number;
}

declare namespace MyClass {
  export interface MyClassMethodOptions {
    width?: number;
    height?: number;
  }
}
```

## Module: Plugin

- Reference material for [Module: Plugin](https://www.typescriptlang.org/docs/handbook/declaration-files/templates/module-plugin-d-ts.html)

Use this template when writing a declaration file for a module that augments another module. A plugin imports a base module and extends its types.

### When to Use

- Your library is imported alongside another library and adds capabilities to it
- You call `require("super-greeter")` and then your plugin augments its behavior
- Example: a charting plugin that adds methods to a base chart library

### Plugin Template

```ts
// Type definitions for [~THE LIBRARY NAME~] [~OPTIONAL VERSION NUMBER~]
// Project: [~THE PROJECT NAME~]
// Definitions by: [~YOUR NAME~] <[~A URL FOR YOU~]>

/*~ This is the module plugin template file. You should rename it to index.d.ts
 *~ and place it in a folder with the same name as the module.
 *~ For example, if you were writing a file for "super-greeter", this
 *~ file should be 'super-greeter/index.d.ts'
 */

/*~ On this line, import the module which this module adds to */
import { greeter } from "super-greeter";

/*~ Here, declare the same module as the one you imported above,
 *~ then expand the existing declaration of the greeter function.
 */
declare module "super-greeter" {
  /*~ Here, declare the things that are added by your plugin.
   *~ You can add new members to existing types.
   */
  interface Greeter {
    printHello(): void;
  }
}
```

### Key Points

- The `import` at the top is required to make this file a module (not a script), which enables `declare module` augmentation.
- The `declare module "super-greeter"` block must exactly match the original module's specifier string.
- Only exported members can be augmented; you cannot add new exports to an existing module.

## Module: Class

- Reference material for [Module: Class](https://www.typescriptlang.org/docs/handbook/declaration-files/templates/module-class-d-ts.html)

Use this template when the module's primary export is a class (constructor function). The library is used like `new Greeter("hello")`.

### Usage Example (JavaScript)

```js
const Greeter = require("super-greeter");
const greeter = new Greeter("Hello, world");
greeter.sayHello();
```

### Module: Class Template

```ts
// Type definitions for [~THE LIBRARY NAME~] [~OPTIONAL VERSION NUMBER~]
// Project: [~THE PROJECT NAME~]
// Definitions by: [~YOUR NAME~] <[~A URL FOR YOU~]>

/*~ This is the module-class template file. You should rename it to index.d.ts
 *~ and place it in a folder with the same name as the module.
 *~ For example, if you were writing a file for "super-greeter", this
 *~ file should be 'super-greeter/index.d.ts'
 */

// Note that ES6 modules cannot directly export class objects.
// This file should be imported using the CommonJS-style:
//   import x = require('[~THE MODULE~]');
//
// Alternatively, if --allowSyntheticDefaultImports or
// --esModuleInterop is turned on, this file can also be
// imported as a default import:
//   import x from '[~THE MODULE~]';
//
// Refer to the TypeScript documentation at
// https://www.typescriptlang.org/docs/handbook/modules.html#export--and-import--require
// to understand common workarounds for this limitation of ES6 modules.

/*~ This declaration specifies that the class constructor function
 *~ is the exported object from the file.
 */
export = MyClass;

/*~ Write your module's methods and properties in this class */
declare class MyClass {
  constructor(someParam?: string);
  someProperty: string[];
  myMethod(opts: MyClass.MyClassMethodOptions): number;
}

/*~ If you want to expose types from your module as well, you can
 *~ place them in this block. Note that if you include this namespace,
 *~ the module can be temporarily used as a namespace, although this
 *~ isn't a recommended use.
 */
declare namespace MyClass {
  /** Documentation comment */
  export interface MyClassMethodOptions {
    width?: number;
    height?: number;
  }
}
```

### Key Points

- `export =` is used because the library uses `module.exports = MyClass` (CommonJS).
- To use this with `import MyClass from "..."` syntax, enable `esModuleInterop` in `tsconfig.json`.
- The `declare namespace MyClass` block lets you export nested types that are accessible as `MyClass.MyClassMethodOptions`.

## Module: Function

- Reference material for [Module: Function](https://www.typescriptlang.org/docs/handbook/declaration-files/templates/module-function-d-ts.html)

Use this template when the module's primary export is a callable function. The library is used like `myFn(42)` after requiring it.

### Usage Example (JavaScript)

```js
const x = require("super-greeter");
const y = x(42);
const z = x("hello");
```

### Module: Function Template

```ts
// Type definitions for [~THE LIBRARY NAME~] [~OPTIONAL VERSION NUMBER~]
// Project: [~THE PROJECT NAME~]
// Definitions by: [~YOUR NAME~] <[~A URL FOR YOU~]>

/*~ This is the module-function template file. You should rename it to index.d.ts
 *~ and place it in a folder with the same name as the module.
 *~ For example, if you were writing a file for "super-greeter", this
 *~ file should be 'super-greeter/index.d.ts'
 */

/*~ This declaration specifies that the function
 *~ is the exported object from the file.
 */
export = MyFunction;

/*~ This example shows how to have multiple overloads of your function */
declare function MyFunction(name: string): MyFunction.NamespaceName;
declare function MyFunction(name: string, greeting: string): MyFunction.NamespaceName;

/*~ If you want to expose types from your module as well, you can
 *~ place them in this block. Often you will want to describe the
 *~ shape of the return type of the function; that type should
 *~ be declared in here as shown.
 */
declare namespace MyFunction {
  export interface NamespaceName {
    firstName: string;
    lastName: string;
  }
}
```

### Key Points

- `export =` is required when the module uses `module.exports = myFunction`.
- Overloads are declared as separate `declare function` statements before the namespace.
- The `declare namespace MyFunction` block is merged with the function declaration, letting the function have properties.

## Global .d.ts

- Reference material for [Global .d.ts](https://www.typescriptlang.org/docs/handbook/declaration-files/templates/global-d-ts.html)

Use this template for libraries loaded via a `<script>` tag that add names to the global scope. No `import` or `require` is involved.

### Identifying Global Libraries

Look at the library's documentation or source for:

- Assignments to `window.myLib` or top-level `var`/`function` declarations
- Documentation showing `<script src="..."></script>` as the installation method
- Usage examples with no `import`/`require` statement
- References to a global like `$` or `_` with no import

### Global Template

```ts
// Type definitions for [~THE LIBRARY NAME~] [~OPTIONAL VERSION NUMBER~]
// Project: [~THE PROJECT NAME~]
// Definitions by: [~YOUR NAME~] <[~A URL FOR YOU~]>

/*~ If this library is callable (e.g. can be invoked as myLib(3)),
 *~ include those call signatures here.
 *~ Otherwise, delete this section.
 */
declare function myLib(a: string): string;
declare function myLib(a: number): number;

/*~ If you want the name of this library to be a valid type name,
 *~ you can do so here.
 *~
 *~ For example, this allows us to write 'var x: myLib'.
 *~ Be sure this actually makes sense! If it doesn't, just
 *~ delete this declaration and add types inside the namespace below.
 */
interface myLib {
  name: string;
  length: number;
  extras?: string[];
}

/*~ If your library has properties exposed on a global variable,
 *~ place them here.
 *~ You should also place types (interfaces and type aliases) here.
 */
declare namespace myLib {
  //~ We can write 'myLib.timeout = 50'
  let timeout: number;
  //~ We can access 'myLib.version', but not change it
  const version: string;
  //~ There's some class we can create via 'let c = new myLib.Cat(42)'
  //~ Or reference, e.g. 'function f(c: myLib.Cat) { ... }'
  class Cat {
    constructor(n: number);
    //~ We can read 'c.age' from a 'Cat' instance
    readonly age: number;
    //~ We can invoke 'c.purr()' from a 'Cat' instance
    purr(): void;
  }
  //~ We can declare a variable as
  //~   'var s: myLib.CatSettings = { weight: 5, name: "Maru" };'
  interface CatSettings {
    weight: number;
    name: string;
    tailLength?: number;
  }
  //~ We can write 'myLib.VetID = 42' or 'myLib.VetID = "bob"'
  type VetID = string | number;
  //~ We can invoke 'myLib.checkCat(c)' or 'myLib.checkCat(c, v)'
  function checkCat(c: Cat, s?: VetID): boolean;
}
```

### Key Points

- Do not include `export` or `import` statements — that would make this a module file, not a global script file.
- Top-level `declare` statements describe what exists in the global scope.
- `declare namespace myLib` groups all properties and types accessible under the `myLib` global.
- An `interface myLib` at the top level (merged with the namespace) allows `myLib` to be used as a type directly.

## Global: Modifying Module

- Reference material for [Global: Modifying Module](https://www.typescriptlang.org/docs/handbook/declaration-files/templates/global-modifying-module-d-ts.html)

Use this template when a library is imported as a module but has the side effect of modifying the global scope (e.g., adding methods to built-in prototypes like `String.prototype`).

### When to Use

- The library is loaded with `require("my-lib")` or `import "my-lib"` for its side effects
- The import adds new methods to existing global types (e.g., `String`, `Array`, `Promise`)
- Usage example: `require("moment"); moment().format("YYYY")` combined with `String.prototype.toDate()`

### Global-Modifying Module Template

```ts
// Type definitions for [~THE LIBRARY NAME~] [~OPTIONAL VERSION NUMBER~]
// Project: [~THE PROJECT NAME~]
// Definitions by: [~YOUR NAME~] <[~A URL FOR YOU~]>

/*~ This is the global-modifying module template file. You should rename it
 *~ to index.d.ts and place it in a folder with the same name as the module.
 *~ For example, if you were writing a file for "super-greeter", this
 *~ file should be 'super-greeter/index.d.ts'
 */

/*~ Note: If your global-modifying module is callable or constructable, you'll
 *~ need to combine the patterns here with those in the module-class or
 *~ module-function template files.
 */
declare global {
  /*~ Here, declare things in the normal global namespace */
  interface String {
    fancyFormat(opts: StringFormatOptions): string;
  }
}

/*~ If your module exports nothing, you'll need this line. Otherwise, delete it */
export {};

/*~ Mark the types that are referenced inside the 'declare global' block here */
export interface StringFormatOptions {
  fancinessLevel: number;
}
```

### Key Points

- The file must be a **module** (contain at least one `export` or `import`) for `declare global` to work. The `export {}` statement at the bottom satisfies this requirement without exporting anything.
- `declare global { }` is the mechanism for adding to the global scope from within a module file.
- If the module also has callable or constructable exports, combine this template with the module-function or module-class template.
- Consumers install the type augmentation simply by importing the module:

```ts
import "super-greeter";

const s = "hello";
s.fancyFormat({ fancinessLevel: 3 }); // OK — added by the module
```

# TypeScript Declaration Files

Reference material for writing and consuming TypeScript declaration files (.d.ts) from the official TypeScript documentation.

## Introduction

- Reference material for [Introduction](https://www.typescriptlang.org/docs/handbook/declaration-files/introduction.html)

Declaration files (`.d.ts`) describe the shape of JavaScript code to TypeScript. They allow the TypeScript compiler to type-check usage of JavaScript libraries that were not written in TypeScript.

There are two primary sources of declaration files:

- **Bundled with a package** — the library author includes `.d.ts` files in the npm package alongside the JavaScript output.
- **DefinitelyTyped (`@types`)** — a community-maintained repository of declaration files for libraries that don't ship their own. Install via `npm install --save-dev @types/<library-name>`.

TypeScript resolves declaration files automatically when using `import` or `require`, looking first at the package's `types` or `typings` field in `package.json`, then for an `index.d.ts` at the package root.

The declaration file guide covers:

1. Writing declarations by example (common patterns)
2. Identifying the correct library structure (global, module, UMD)
3. Do's and Don'ts for avoiding common mistakes
4. A deep dive into how declarations work internally
5. How to publish and consume declaration files

## Declaration Reference

- Reference material for [Declaration Reference](https://www.typescriptlang.org/docs/handbook/declaration-files/by-example.html)

Common patterns for writing declaration files, organized by the kind of thing being declared.

### Global Variables

```ts
/** The number of widgets present */
declare var foo: number;
```

### Global Functions

```ts
declare function greet(greeting: string): void;
```

Functions can have overloads:

```ts
declare function getWidget(n: number): Widget;
declare function getWidget(s: string): Widget[];
```

### Objects with Properties

Use `declare namespace` to describe objects accessed via dotted notation:

```ts
declare namespace myLib {
  function makeGreeting(s: string): string;
  let numberOfGreetings: number;
}
```

Usage: `myLib.makeGreeting("hello")` and `myLib.numberOfGreetings`.

### Reusable Types — Interfaces

```ts
interface GreetingSettings {
  greeting: string;
  duration?: number;
  color?: string;
}

declare function greet(setting: GreetingSettings): void;
```

### Reusable Types — Type Aliases

```ts
type GreetingLike = string | (() => string) | MyGreeter;

declare function greet(g: GreetingLike): void;
```

### Organizing Types with Nested Namespaces

```ts
declare namespace GreetingLib {
  interface LogOptions {
    verbose?: boolean;
  }
  interface AlertOptions {
    modal: boolean;
    title?: string;
    color?: string;
  }
}
```

These are referenced as `GreetingLib.LogOptions` and `GreetingLib.AlertOptions`.

Namespaces can be nested:

```ts
declare namespace GreetingLib.Options {
  interface Log {
    verbose?: boolean;
  }
  interface Alert {
    modal: boolean;
    title?: string;
    color?: string;
  }
}
```

### Classes

```ts
declare class Greeter {
  constructor(greeting: string);
  greeting: string;
  showGreeting(): void;
}
```

### Enums

```ts
declare enum Shading {
  None,
  Streamline,
  Matte,
  Glossy,
}
```

### Modules (CommonJS / ESM exports)

Use `export =` for CommonJS-style modules (when the library uses `module.exports = ...`):

```ts
export = MyModule;

declare function MyModule(): void;
declare namespace MyModule {
  let version: string;
}
```

Use named exports for ESM-style:

```ts
export function myFunction(a: string): string;
export const myField: number;
export interface SomeType {
  name: string;
  length: number;
}
```

### UMD Modules

Libraries usable both as globals and as modules use `export as namespace`:

```ts
export as namespace myLib;
export function makeGreeting(s: string): string;
export let numberOfGreetings: number;
```

## Library Structures

- Reference material for [Library Structures](https://www.typescriptlang.org/docs/handbook/declaration-files/library-structures.html)

Choosing the correct declaration file structure depends on how the library is consumed.

### Global Libraries

A global library is accessible from the global scope — no `import` or `require` needed. Examples: older jQuery (`$()`), Underscore.js (old style).

Identifying characteristics in JavaScript source:

- Top-level `var` statements or `function` declarations
- `window.myLib = ...` assignments
- References to `document` or `window`

Use the `global.d.ts` template.

```ts
declare function myLib(a: string): string;
declare namespace myLib {
  let timeout: number;
}
```

### Module Libraries

Libraries consumed via `require()` or `import`. Most modern npm packages are module libraries.

Identifying characteristics:

- `const x = require("foo")` or `import x from "foo"` in usage examples
- `exports.myFn = ...` or `module.exports = ...` in the source
- `define(...)` (AMD) in the source

Use the `module.d.ts` template.

### UMD Libraries

Libraries that can be used as a global (via a `<script>` tag) or as a module (via `require`/`import`). Most modern utility libraries (e.g. Moment.js) are UMD.

Identifying pattern in library source:

```js
(function (root, factory) {
  if (typeof define === "function" && define.amd) {
    define(["libName"], factory);
  } else if (typeof module === "object" && module.exports) {
    module.exports = factory(require("libName"));
  } else {
    root.returnExports = factory(root.libName);
  }
}(this, function (b) { ... }));
```

Use `export as namespace` in the declaration file to expose the global.

### Module Plugins

A module plugin imports another module and extends it. The declaration file imports the original module and uses `declare module` to augment it.

Use the `module-plugin.d.ts` template.

### Global Plugins

A script that adds properties to a global (e.g. adds methods to `Array.prototype`). The declaration file uses `interface` merging on the global type.

### Global-Modifying Modules

A module that, when `require`d/`import`ed, modifies the global scope as a side effect. The declaration file uses `declare global { }` inside a module file.

Use the `global-modifying-module.d.ts` template.

## Do's and Don'ts

- Reference material for [Do's and Don'ts](https://www.typescriptlang.org/docs/handbook/declaration-files/do-s-and-don-ts.html)

### General Types

**Don't** use the object wrapper types `Number`, `String`, `Boolean`, `Symbol`, or `Object`. These refer to boxed object types and are almost never what you want.

```ts
/* WRONG */
function reverse(s: String): String;

/* OK */
function reverse(s: string): string;
```

**Do** use `object` (lowercase) for non-primitive types when needed, or better yet, use a specific interface or type.

### Callback Return Types

**Don't** use `any` as the return type for a callback whose return value will be ignored:

```ts
/* WRONG */
function fn(x: () => any) {
  x();
}
```

**Do** use `void` — it prevents accidentally using the return value in an unsafe way:

```ts
/* OK */
function fn(x: () => void) {
  x();
}
```

### Optional Parameters in Callbacks

**Don't** use optional parameters in callbacks unless you actually intend to call the callback with fewer arguments:

```ts
/* WRONG */
interface Fetcher {
  getObject(done: (data: unknown, elapsedTime?: number) => void): void;
}
```

**Do** write callback parameters as required:

```ts
/* OK */
interface Fetcher {
  getObject(done: (data: unknown, elapsedTime: number) => void): void;
}
```

### Overloads and Callbacks

**Don't** write separate overloads differing only by callback arity:

```ts
/* WRONG */
declare function beforeAll(action: () => void, timeout?: number): void;
declare function beforeAll(
  action: (done: DoneFn) => void,
  timeout?: number
): void;
```

**Do** write a single overload using the maximum arity:

```ts
/* OK */
declare function beforeAll(
  action: (done: DoneFn) => void,
  timeout?: number
): void;
```

### Ordering Overloads

**Don't** put more general overloads before more specific ones:

```ts
/* WRONG */
declare function fn(x: any): any;
declare function fn(x: HTMLElement): number;
declare function fn(x: HTMLDivElement): string;

var myElem: HTMLDivElement;
var x = fn(myElem); // x: any — wrong!
```

**Do** put more specific overloads before more general ones:

```ts
/* OK */
declare function fn(x: HTMLDivElement): string;
declare function fn(x: HTMLElement): number;
declare function fn(x: any): any;

var myElem: HTMLDivElement;
var x = fn(myElem); // x: string — correct!
```

### Use Optional Parameters Instead of Overloads

**Don't** write overloads that differ only in trailing optional parameters:

```ts
/* WRONG */
interface Example {
  diff(one: string): number;
  diff(one: string, two: string): number;
  diff(one: string, two: string, three: boolean): number;
}
```

**Do** use optional parameters:

```ts
/* OK */
interface Example {
  diff(one: string, two?: string, three?: boolean): number;
}
```

### Use Union Types Instead of Overloads

**Don't** write overloads that differ only by the type of one parameter when a union type would express the same thing:

```ts
/* WRONG */
interface Moment {
  utcOffset(): number;
  utcOffset(b: number): Moment;
  utcOffset(b: string): Moment;
}
```

**Do** use a union type:

```ts
/* OK */
interface Moment {
  utcOffset(): number;
  utcOffset(b: number | string): Moment;
}
```

## Deep Dive

- Reference material for [Deep Dive](https://www.typescriptlang.org/docs/handbook/declaration-files/deep-dive.html)

### Declaration Types: Namespace, Type, Value

In TypeScript, a declaration can create one or more of three things: a **namespace**, a **type**, or a **value**.

| Declaration Type  | Namespace | Type | Value |
|-------------------|-----------|------|-------|
| Namespace         | X         |      | X     |
| Class             |           | X    | X     |
| Enum              |           | X    | X     |
| Interface         |           | X    |       |
| Type Alias        |           | X    |       |
| Function          |           |      | X     |
| Variable          |           |      | X     |

Understanding which of these a declaration creates determines how it can be used and combined.

### Simple Combinations

When a name is used both as a type and as a value, TypeScript merges the declarations:

```ts
// This creates both a type and a value named 'Foo'
class Foo {
  static bar: string;
}
```

### Namespace + Interface Merging

Interfaces and namespaces with the same name are merged:

```ts
interface Point {
  x: number;
  y: number;
}

namespace Point {
  export function distance(p1: Point, p2: Point): number;
}
```

Now `Point` is both a type (describing the object shape) and a namespace (containing the `distance` function).

### Namespace + Class Merging

A namespace merged with a class adds static members:

```ts
class Album {
  label: Album.AlbumLabel;
}

namespace Album {
  export class AlbumLabel {}
}
```

### Namespace + Function Merging

A namespace merged with a function adds properties to the function:

```ts
function buildLabel(name: string): string {
  return buildLabel.prefix + name + buildLabel.suffix;
}

namespace buildLabel {
  export let suffix = "";
  export let prefix = "Hello, ";
}
```

### The `declare` Keyword

The `declare` keyword is used in `.d.ts` files to tell TypeScript about the existence of a value without providing an implementation. It can be applied to variables, functions, classes, modules, namespaces, and enums.

```ts
declare var myGlobal: string;
declare function doSomething(x: number): void;
declare class MyClass {
  constructor();
  method(): string;
}
declare namespace myNamespace {
  var value: number;
}
```

### Ambient Modules

Use `declare module` to describe modules that TypeScript can't find automatically:

```ts
declare module "path" {
  export function join(...paths: string[]): string;
  export function resolve(...paths: string[]): string;
}
```

Wildcard module declarations match any module name pattern:

```ts
declare module "*.svg" {
  const content: string;
  export default content;
}
```

### Declaration File Resolution

TypeScript resolves `.d.ts` files in this order:

1. The `types` / `typings` field in `package.json`
2. `index.d.ts` in the package root
3. `@types/<name>` in `node_modules`
4. Files listed in `typeRoots` in `tsconfig.json`
5. Specific packages listed in `types` in `tsconfig.json`

### Triple-Slash Directives

Triple-slash directives are single-line comments at the top of a file that reference other declaration files:

```ts
/// <reference path="./other-declarations.d.ts" />
/// <reference types="node" />
/// <reference lib="es2015.promise" />
```

- `path` — references a local `.d.ts` file by relative path
- `types` — references an `@types` package
- `lib` — includes a built-in TypeScript lib file

## Publishing

- Reference material for [Publishing](https://www.typescriptlang.org/docs/handbook/declaration-files/publishing.html)

### Option 1 — Bundle Declarations with Your Package

Include `.d.ts` files in your npm package alongside the compiled JavaScript.

**Configure `tsconfig.json`:**

```json
{
  "compilerOptions": {
    "declaration": true,
    "outDir": "./lib"
  }
}
```

**Point to declarations in `package.json`:**

```json
{
  "name": "awesome",
  "author": "Vandelay Industries",
  "version": "1.0.0",
  "main": "./lib/main.js",
  "types": "./lib/main.d.ts"
}
```

Both `"types"` and `"typings"` are accepted field names. If the main declaration file is named `index.d.ts` and lives in the package root, the `"types"` field is optional.

### Option 2 — Publish to DefinitelyTyped

If you don't own the library, submit declaration files to the [DefinitelyTyped](https://github.com/DefinitelyTyped/DefinitelyTyped) repository. Published packages appear as `@types/<name>` on npm.

### Supporting Multiple TypeScript Versions

Use `typesVersions` in `package.json` to ship different declarations for different TypeScript compiler versions:

```json
{
  "name": "awesome",
  "version": "1.0.0",
  "typesVersions": {
    ">=4.0": {
      "*": ["ts4.0/*"]
    },
    ">=3.1": {
      "*": ["ts3.1/*"]
    }
  }
}
```

TypeScript picks the first matching range when resolving types.

### Dependencies on Other Type Packages

If your declaration file uses types from another `@types` package, declare that dependency in `package.json`. Use `"dependencies"` (not `"devDependencies"`) so that consumers get the required types automatically:

```json
{
  "dependencies": {
    "@types/node": "*"
  }
}
```

## Consumption

- Reference material for [Consumption](https://www.typescriptlang.org/docs/handbook/declaration-files/consumption.html)

### Installing Type Declarations

For libraries that don't bundle their own declarations, install the community-maintained types from DefinitelyTyped:

```sh
npm install --save-dev @types/lodash
```

Once installed, you can use the library with full type safety:

```ts
import * as _ from "lodash";
_.padStart("Hello TypeScript!", 20, " ");
```

TypeScript automatically finds `@types` packages in `node_modules/@types` without any additional configuration.

### Controlling Which Types Are Included

By default, TypeScript includes all packages found under `node_modules/@types`. You can restrict this with `tsconfig.json` options.

**`typeRoots`** — specifies directories to search for type packages (replaces the default `@types` lookup):

```json
{
  "compilerOptions": {
    "typeRoots": ["./typings", "./vendor/types"]
  }
}
```

**`types`** — specifies an explicit list of `@types` packages to include:

```json
{
  "compilerOptions": {
    "types": ["node", "lodash", "express"]
  }
}
```

With `"types"` set, only the listed packages are included. Other `@types` packages in `node_modules` will not be automatically included.

These options affect only globally-scoped declarations. Explicitly imported packages (via `import`) are always included regardless of these settings.

