## TypeScript Index Signatures

- Reference [Index Signatures](https://www.w3schools.com/typescript/typescript_index_signatures.php)

### Basic String Index Signatures

```ts
// This interface represents an object with string keys and string values
interface StringDictionary {
  [key: string]: string;
}

// Creating a compliant object
const names: StringDictionary = {
  firstName: "Alice",
  lastName: "Smith",
  "100": "One Hundred"
};

// Accessing properties
console.log(names["firstName"]); // "Alice"
console.log(names["lastName"]); // "Smith"
console.log(names["100"]); // "One Hundred"

// Adding new properties dynamically
names["age"] = "30";

// This would cause an error
// names["age"] = 30; // Error: Type 'number' is not assignable to type 'string'
```

### Basic Number Index Signatures

```ts
// Object with number indexes
interface NumberDictionary {
  [index: number]: any;
}

const scores: NumberDictionary = {
  0: "Zero",
  1: 100,
  2: true
};

console.log(scores[0]); // "Zero"
console.log(scores[1]); // 100
console.log(scores[2]); // true

// Adding a complex object
scores[3] = { passed: true };
```

### Combining Index Signatures with Named Properties

```ts
interface UserInfo {
  name: string; // Required property with specific name
  age: number;  // Required property with specific name
  [key: string]: string | number; // All other properties must be string or number
}

const user: UserInfo = {
  name: "Alice", // Required
  age: 30,      // Required
  address: "123 Main St", // Optional
  zipCode: 12345 // Optional
};

// This would cause an error
// const invalidUser: UserInfo = {
//  name: "Bob",
//  age: "thirty", // Error: Type 'string' is not assignable to type 'number'
//  isAdmin: true  // Error: Type 'boolean' is not assignable to type 'string | number'
// };
```

### Readonly Index Signatures

```ts
interface ReadOnlyStringArray {
  readonly [index: number]: string;
}

const names: ReadOnlyStringArray = ["Alice", "Bob", "Charlie"];

console.log(names[0]); // "Alice"

// This would cause an error
// names[0] = "Andrew";
// Error: Index signature in type 'ReadOnlyStringArray' only permits reading
```

### Real-World API Response Example

```ts
// Type for API responses with dynamic keys
interface ApiResponse<T> {
  data: {
    [resourceType: string]: T[];  // e.g., { "users": User[], "posts": Post[] }
  };
  meta: {
    page: number;
    total: number;
    [key: string]: any;  // Allow additional metadata
  };
}

// Example usage with a users API
interface User {
  id: number;
  name: string;
  email: string;
}

// Mock API response
const apiResponse: ApiResponse<User> = {
  data: {
    users: [
      { id: 1, name: "Alice", email: "alice@example.com" },
      { id: 2, name: "Bob", email: "bob@example.com" }
    ]
  },
  meta: {
    page: 1,
    total: 2,
    timestamp: "2023-01-01T00:00:00Z"
  }
};

// Accessing the data
const users = apiResponse.data.users;
console.log(users[0].name);  // "Alice"
```

### Index Signature Type Compatibility

```ts
interface ConflictingTypes {
  [key: string]: number;
  name: string; // Error: not assignable to string index type 'number'
}

interface FixedTypes {
  [key: string]: number | string;
  name: string;  // OK
  age: number;   // OK
}
```

## TypeScript Declaration Merging

- Reference [Declaration Merging](https://www.w3schools.com/typescript/typescript_declaration_merging.php)

### Interface Merging

```ts
// First declaration
interface Person {
  name: string;
  age: number;
}

// Second declaration with the same name
interface Person {
  address: string;
  email: string;
}

// TypeScript merges them into:
// interface Person {
//   name: string;
//   age: number;
//   address: string;
//   email: string;
// }

const person: Person = {
  name: "John",
  age: 30,
  address: "123 Main St",
  email: "john@example.com"
};

console.log(person);
```

### Function Overloads

```ts
// Function overloads
function processValue(value: string): string;
function processValue(value: number): number;
function processValue(value: boolean): boolean;

// Implementation that handles all overloads
function processValue(value: string | number | boolean): string | number | boolean {
  if (typeof value === "string") {
    return value.toUpperCase();
  } else if (typeof value === "number") {
    return value * 2;
  } else {
    return !value;
  }
}

// Using the function with different types
console.log(processValue("hello"));  // "HELLO"
console.log(processValue(10));       // 20
console.log(processValue(true));     // false
```

### Namespace Merging

```ts
namespace Validation {
  export interface StringValidator {
    isValid(s: string): boolean;
  }
}

namespace Validation {
  export interface NumberValidator {
    isValid(n: number): boolean;
  }

  export class ZipCodeValidator implements StringValidator {
    isValid(s: string): boolean {
      return s.length === 5 && /^\d+$/.test(s);
    }
  }
}

// After merging:
// namespace Validation {
//   export interface StringValidator { isValid(s: string): boolean; }
//   export interface NumberValidator { isValid(n: number): boolean; }
//   export class ZipCodeValidator implements StringValidator { ... }
// }

// Using the merged namespace
const zipValidator = new Validation.ZipCodeValidator();

console.log(zipValidator.isValid("12345"));  // true
console.log(zipValidator.isValid("1234"));   // false
console.log(zipValidator.isValid("abcde"));  // false
```

### Class and Interface Merging

```ts
// Interface declaration
interface Cart {
  calculateTotal(): number;
}

// Class declaration with same name
class Cart {
  items: { name: string; price: number }[] = [];

  addItem(name: string, price: number): void {
    this.items.push({ name, price });
  }

  // Must implement the interface method
  calculateTotal(): number {
    return this.items.reduce((sum, item) => sum + item.price, 0);
  }
}

// Using the merged class and interface
const cart = new Cart();
cart.addItem("Book", 15.99);
cart.addItem("Coffee Mug", 8.99);

console.log(`Total: $${cart.calculateTotal().toFixed(2)}`);
```

### Enum Merging

```ts
// First part of the enum
enum Direction {
  North,
  South
}

// Second part of the enum
enum Direction {
  East = 2,
  West = 3
}

// After merging:
// enum Direction {
//   North = 0,
//   South = 1,
//   East = 2,
//   West = 3
// }

console.log(Direction.North);  // 0
console.log(Direction.South);  // 1
console.log(Direction.East);   // 2
console.log(Direction.West);   // 3

// Can also access by value
console.log(Direction[0]);     // "North"
console.log(Direction[2]);     // "East"
```

### Module Augmentation

```ts
// Original library definition
// Imagine this comes from a third-party library
declare namespace LibraryModule {
  export interface User {
    id: number;
    name: string;
  }
  export function getUser(id: number): User;
}

// Augmenting with additional functionality (your code)
declare namespace LibraryModule {
  // Add new interface
  export interface UserPreferences {
    theme: string;
    notifications: boolean;
  }

  // Add new property to existing interface
  export interface User {
    preferences?: UserPreferences;
  }

  // Add new function
  export function getUserPreferences(userId: number): UserPreferences;
}

// Using the augmented module
const user = LibraryModule.getUser(123);
console.log(user.preferences?.theme);

const prefs = LibraryModule.getUserPreferences(123);
console.log(prefs.notifications);
```

# TypeScript with JavaScript

Reference material for using TypeScript in JavaScript projects, type checking JS files, and working with JSDoc from the official TypeScript documentation.

## JS Projects Utilizing TypeScript

- Reference material for [JS Projects Utilizing TypeScript](https://www.typescriptlang.org/docs/handbook/intro-to-js-ts.html)

TypeScript offers varying levels of type checking for JavaScript files. The type system can infer types from JS code, and JSDoc annotations can provide explicit type information.

**Levels of type checking in JS files:**

| Level | How to enable | What it does |
|---|---|---|
| Per-file loose check | `// @ts-check` at top of file | Basic type inference and error reporting |
| Per-file disable | `// @ts-nocheck` at top of file | Disables all checking for that file |
| Project-wide | `"checkJs": true` in tsconfig | Checks all `.js` files in the project |
| JS in TS project | `"allowJs": true` in tsconfig | Allows `.js` files alongside `.ts` files |

**Per-file check with `// @ts-check`:**

```js
// @ts-check
let itsAString = "hello!";
itsAString = 123;
// Error: Type 'number' is not assignable to type 'string'.
```

**Suppressing specific errors with `// @ts-ignore`:**

```js
// @ts-check
let myValue = "hello";
// @ts-ignore
myValue = 42; // No error on this line
```

**Suppressing with `// @ts-expect-error`** (preferred — fails if no error exists):

```js
// @ts-check
// @ts-expect-error
let x = "hello";
x = 42;
```

**Using JSDoc for explicit typing in JS:**

```js
// @ts-check
/** @type {string} */
let myString;

/** @param {string} name */
function greet(name) {
  console.log("Hello " + name);
}
```

**Project-level configuration with `tsconfig.json`:**

```json
{
  "compilerOptions": {
    "allowJs": true,
    "checkJs": true,
    "outDir": "./dist",
    "target": "ES2020"
  },
  "include": ["src/**/*"]
}
```

**`jsconfig.json`** is a tsconfig with `allowJs` implicitly true and is treated by editors as the configuration for a JavaScript project. Most tsconfig options are also valid in jsconfig.json.

```json
{
  "compilerOptions": {
    "checkJs": true,
    "target": "ES2020",
    "module": "CommonJS",
    "moduleResolution": "node"
  },
  "exclude": ["node_modules", "**/node_modules/*"]
}
```

## Type Checking JavaScript Files

- Reference material for [Type Checking JavaScript Files](https://www.typescriptlang.org/docs/handbook/type-checking-javascript-files.html)

TypeScript's type checker applies different inference rules to JavaScript files compared to TypeScript files.

**Key differences between JS and TS type checking:**

1. Types are optional — missing types are inferred rather than required
2. Types for classes are inferred from usage across the file
3. Objects can gain properties after creation
4. Function parameters are not checked against each other unless JSDoc is used

**Inferring class properties from constructor assignments:**

```js
// @ts-check
class Animal {
  constructor(name) {
    /** @type {string} */
    this.name = name;
    this.numLegs = 4; // TypeScript infers: number
  }
}
```

**Object property inference — properties can be added after the fact:**

```js
// @ts-check
let obj = {};
obj.name = "hello";  // OK in JS checking; would be an error in TS
obj.value = 42;      // OK
```

**CommonJS module imports are supported:**

```js
// @ts-check
const fs = require("fs");
module.exports.fn = function() { return 1; };
```

**Differences in function type checking:**

```js
// @ts-check
/** @param {string | number} value */
function padLeft(value, padding) {
  // padding is implicitly any; no error without JSDoc
  return " ".repeat(padding) + value;
}
```

**Special JSDoc forms that affect type checking:**

```js
// @ts-check
/** @type {{ x: number, y: number }} */
let point = { x: 0, y: 0 };

/**
 * @param {string} name
 * @returns {string}
 */
function greet(name) {
  return "Hello, " + name;
}
```

**Casting with JSDoc `@type` in parentheses:**

```js
// @ts-check
const value = /** @type {string} */ (someValue);
```

**`noImplicitAny` in JS files** — can be enabled to require explicit types on parameters:

```json
{
  "compilerOptions": {
    "checkJs": true,
    "noImplicitAny": true
  }
}
```

**Key behaviors unique to JS checking:**

- `arguments` object is always available in functions
- Module detection may differ from TS files
- `undefined` vs undeclared variables handled more loosely
- Prototype property assignments are tracked for class-like patterns:

```js
// @ts-check
function MyClass(name) {
  this.name = name;
}
MyClass.prototype.greet = function() {
  return "Hello, " + this.name; // `this` is typed as MyClass
};
```

## JSDoc Reference

- Reference material for [JSDoc Reference](https://www.typescriptlang.org/docs/handbook/jsdoc-supported-types.html)

TypeScript supports a subset of JSDoc tags for type annotation in JavaScript files. These tags allow JavaScript code to benefit from TypeScript's type system without converting to `.ts` files.

**`@type`** — declares the type of a variable, parameter, or property:

```js
/** @type {string} */
let myStr;

/** @type {number | string} */
let numOrStr;

/** @type {Array<string>} */
let strArray;

/** @type {string[]} */
let strArray2;

/** @type {{ id: number, name: string }} */
let user;

/** @type {Object.<string, number>} */
let mapOfNumbers;

/** @type {function(string, boolean): number} */
let fn;

/** @type {(s: string, b: boolean) => number} */
let fn2;
```

**`@param` and `@returns`** — types for function parameters and return values:

```js
/**
 * @param {string}  p1 - A string param
 * @param {string=} p2 - An optional param (Closure syntax)
 * @param {string} [p3] - Another optional param (JSDoc syntax)
 * @param {string} [p4="test"] - An optional param with a default
 * @returns {string} This is the result
 */
function stringsStringStrings(p1, p2, p3, p4) {
  // TODO
}
```

**`@typedef`** — defines a custom type that can be reused:

```js
/**
 * @typedef {Object} SpecialType - creates a new type named 'SpecialType'
 * @property {string} prop1 - a string property of SpecialType
 * @property {number} prop2 - a number property of SpecialType
 * @property {number=} prop3 - an optional number property of SpecialType
 */

/** @type {SpecialType} */
let specialTypeObject;
```

**Shorthand `@typedef`:**

```js
/** @typedef {(data: string, index?: number) => boolean} Predicate */
```

**`@callback`** — like `@typedef` but for function types:

```js
/**
 * @callback Predicate
 * @param {string} data
 * @param {number} [index]
 * @returns {boolean}
 */

/** @type {Predicate} */
const ok = (s) => !(s.length % 2);
```

**`@template`** — declares generic type parameters:

```js
/**
 * @template T
 * @param {T} x
 * @returns {T}
 */
function identity(x) {
  return x;
}

// With constraints:
/**
 * @template {string} K - K must be a string or string literal
 * @template {{ serious(): string }} Seriousalizable
 * @param {K} key
 * @param {Seriousalizable} object
 */
function seriousalize(key, object) {
  // ....
}
```

**`@satisfies`** — validates that a value conforms to a type without changing the inferred type:

```js
// @ts-check
/**
 * @satisfies {Record<string, string>}
 */
const palette = {
  red: [255, 0, 0],    // Error: number[] is not string
  green: "#00ff00",
  blue: [0, 0, 255],   // Error: number[] is not string
};
```

**`@class` / `@constructor`** — marks a function as a constructor:

```js
/**
 * @constructor
 * @param {string} name
 */
function Person(name) {
  this.name = name;
}
const p = new Person("Alice");
```

**`@this`** — specifies the type of `this` inside a function:

```js
/**
 * @this {HTMLElement}
 * @param {*} e
 */
function callbackForLater(e) {
  this.clientHeight = parseInt(e);
}
```

**`@extends` / `@augments`** — specifies the superclass type for JS class inheritance:

```js
/**
 * @extends {Base<string>}
 */
class SpecializedDerived extends Base {
  // ...
}
```

**`@enum`** — marks an object as an enum where all properties have a consistent type:

```js
/** @enum {number} */
const JSDocState = {
  BeginningOfLine: 0,
  SawAsterisk: 1,
  SavingComments: 2,
};
```

**`@override`** — marks a method as overriding a base class method:

```js
class Animal {
  greet() { return "Hello!"; }
}
class Dog extends Animal {
  /** @override */
  greet() { return "Woof!"; }
}
```

**`@readonly`** — marks a property as read-only:

```js
class Foo {
  constructor() {
    /** @readonly */
    this.id = Math.random();
  }
}
const foo = new Foo();
foo.id = 5; // Error: Cannot assign to 'id' because it is a read-only property.
```

**`@deprecated`** — marks a symbol as deprecated with an optional message:

```js
/** @deprecated Use newFunction instead */
function oldFunction() {}
```

**`@overload`** — declares multiple call signatures for a function (TypeScript 5.0+):

```js
// @ts-check
/**
 * @overload
 * @param {string} value
 * @returns {void}
 */
/**
 * @overload
 * @param {number} value
 * @returns {void}
 */
/**
 * @param {string | number} value
 * @returns {void}
 */
function printValue(value) {
  console.log(value);
}
```

**`@import`** — imports types from other files (TypeScript 5.5+):

```js
// @ts-check
/** @import { SomeType } from "./module" */

/** @type {SomeType} */
let x;
```

**Importing types with `@type` using `import()`:**

```js
/** @type {import("./some-module").SomeType} */
let myVar;
```

**Cast syntax** — force a type with a `@type` comment wrapping a parenthesized expression:

```js
// @ts-check
const value = /** @type {string} */ (someUnknownValue);
```

## Creating .d.ts Files from .js files

- Reference material for [Creating .d.ts Files from .js files](https://www.typescriptlang.org/docs/handbook/declaration-files/dts-from-js.html)

TypeScript can automatically generate `.d.ts` declaration files from JavaScript source files, making it possible to add type definitions to existing JavaScript packages without rewriting them in TypeScript.

**Requirements to generate `.d.ts` from `.js`:**

- TypeScript 3.7 or later
- `allowJs: true` — allow JavaScript input files
- `declaration: true` — emit `.d.ts` files
- `emitDeclarationOnly: true` — emit only `.d.ts`, no `.js` output (optional but common)

**Minimal `tsconfig.json` to generate declarations:**

```json
{
  "compilerOptions": {
    "allowJs": true,
    "declaration": true,
    "emitDeclarationOnly": true,
    "outDir": "types"
  },
  "include": ["src/**/*"]
}
```

**Emit declarations alongside compiled output:**

```json
{
  "compilerOptions": {
    "allowJs": true,
    "declaration": true,
    "outDir": "dist"
  }
}
```

**Example — JS source with JSDoc:**

```js
// src/index.js
/**
 * @param {string} name
 * @returns {string}
 */
export function greet(name) {
  return "Hello, " + name;
}

/** @type {number} */
export const version = 1;
```

**Generated `.d.ts` output:**

```ts
// types/index.d.ts
export function greet(name: string): string;
export const version: number;
```

**Classes with JSDoc produce full `.d.ts`:**

```js
// src/dog.js
export class Dog {
  /** @param {string} name */
  constructor(name) {
    this.name = name;
  }

  /** @returns {string} */
  bark() {
    return "Woof!";
  }
}
```

**Generated output:**

```ts
export class Dog {
  constructor(name: string);
  name: string;
  bark(): string;
}
```

**`@typedef` generates type aliases in `.d.ts`:**

```js
/**
 * @typedef {Object} Config
 * @property {string} host
 * @property {number} port
 */

/**
 * @param {Config} config
 */
export function connect(config) { }
```

**Generated output:**

```ts
export type Config = {
  host: string;
  port: number;
};
export function connect(config: Config): void;
```

**Using `declarationDir` to separate declaration output:**

```json
{
  "compilerOptions": {
    "allowJs": true,
    "declaration": true,
    "declarationDir": "./types",
    "outDir": "./dist"
  }
}
```

**Referencing generated declarations from `package.json`:**

```json
{
  "name": "my-js-package",
  "main": "dist/index.js",
  "types": "types/index.d.ts"
}
```

**Limitations of auto-generated `.d.ts` from JS:**

- Without JSDoc annotations, types will often be inferred as `any`
- Complex runtime patterns (mixins, dynamic property assignment) may not generate accurate types
- The generated declarations reflect TypeScript's best inference — manual adjustments may be needed
- Some JSDoc patterns (like `@typedef` in one file used across files) require `declaration: true` with careful file structuring

#!/usr/bin/env node
/**
 * Bun TypeScript Workflow Helper
 *
 * Detects Bun, generates Bun-optimised configs, and guides setup.
 *
 * Usage:
 *   node bun-workflow.js --detect         # Detect Bun and show version
 *   node bun-workflow.js --tsconfig       # Print Bun-optimised tsconfig.json
 *   node bun-workflow.js --bunfig         # Print bunfig.toml template
 *   node bun-workflow.js --scripts        # Print package.json scripts for Bun
 *   node bun-workflow.js --migrate        # Show Node.js → Bun migration steps
 *   node bun-workflow.js --test           # Run built-in makeshift tests
 *
 * Self-contained — no external dependencies required.
 */

import { execSync } from 'child_process';
import { existsSync } from 'fs';

// ─── CLI flags ───────────────────────────────────────────────────────────────
const args           = process.argv.slice(2);
const DETECT         = args.includes('--detect');
const SHOW_TSCONFIG  = args.includes('--tsconfig');
const SHOW_BUNFIG    = args.includes('--bunfig');
const SHOW_SCRIPTS   = args.includes('--scripts');
const SHOW_MIGRATE   = args.includes('--migrate');
const TEST           = args.includes('--test');
const SHOW_HELP      = args.length === 0 || args.includes('--help');

// ─── Colours ─────────────────────────────────────────────────────────────────
const c = {
  green:  (s) => `\x1b[32m${s}\x1b[0m`,
  red:    (s) => `\x1b[31m${s}\x1b[0m`,
  yellow: (s) => `\x1b[33m${s}\x1b[0m`,
  cyan:   (s) => `\x1b[36m${s}\x1b[0m`,
  bold:   (s) => `\x1b[1m${s}\x1b[0m`,
  dim:    (s) => `\x1b[2m${s}\x1b[0m`,
};

// ─── Utilities ───────────────────────────────────────────────────────────────

function tryRun(cmd) {
  try {
    return execSync(cmd, { encoding: 'utf8', stdio: 'pipe' }).trim();
  } catch {
    return null;
  }
}

/** Detect Bun and return version string, or null if not installed. */
function detectBun() {
  return tryRun('bun --version');
}

/** Check if we're inside a git repo. */
function isGitRepo() {
  return existsSync('.git') || tryRun('git rev-parse --is-inside-work-tree') === 'true';
}

// ─── Template generators ─────────────────────────────────────────────────────

/**
 * Returns Bun-optimised tsconfig.json content.
 * @param {'app'|'lib'|'react'} [target='app']
 * @returns {object}
 */
function buildBunTsconfig(target = 'app') {
  const base = {
    compilerOptions: {
      // Bun supports these natively
      target: 'ESNext',
      lib: target === 'react' ? ['ESNext', 'DOM', 'DOM.Iterable'] : ['ESNext'],
      module: 'Preserve',           // best for Bun
      moduleResolution: 'Bundler',  // required for module: Preserve
      // Output
      outDir: './dist',
      rootDir: './src',
      declaration: true,
      declarationMap: true,
      sourceMap: true,
      // Strictness
      strict: true,
      noUncheckedIndexedAccess: true,
      exactOptionalPropertyTypes: true,
      noImplicitOverride: true,
      noImplicitReturns: true,
      noFallthroughCasesInSwitch: true,
      noUnusedLocals: true,
      noUnusedParameters: true,
      // Interop
      esModuleInterop: true,
      allowSyntheticDefaultImports: true,
      skipLibCheck: true,
      forceConsistentCasingInFileNames: true,
      // Bun globals
      types: target === 'app' ? ['bun-types'] : [],
    },
    include: ['src'],
    exclude: ['node_modules', 'dist'],
  };

  if (target === 'react') {
    base.compilerOptions.jsx = 'react-jsx';
  }

  return base;
}

/**
 * Returns a bunfig.toml template string.
 * @param {object} opts
 * @param {string} [opts.testDir='src']
 * @param {boolean} [opts.coverage=true]
 * @returns {string}
 */
function buildBunfig(opts = {}) {
  const { testDir = 'src', coverage = true } = opts;
  return `# bunfig.toml — Bun configuration
# Reference: https://bun.sh/docs/runtime/bunfig

[install]
# Use exact versions (like npm --save-exact)
exact = false
# Lifecycle scripts (postinstall etc.) — set false for untrusted packages
lifecycle = true
# Auto-install types on install
auto = "auto"
# Dedupe on install
dedupe = false

[install.scopes]
# Scoped registry configuration (example)
# "@myorg" = { url = "https://registry.myorg.com/", token = "$NPM_TOKEN" }

[run]
# Default shell for bun run scripts
# shell = "system"
# Automatically load .env file
# bun automatically loads .env, .env.local, .env.development, .env.production

[test]
# Root directory for test files
root = "${testDir}"
# Coverage
coverage = ${coverage}
coverageThreshold = { line = 80, function = 80, statement = 80 }
# Timeout per test (ms)
timeout = 5000
# Reporter
reporter = "default"
# Preload file (equivalent to jest setupFilesAfterFramework)
# preload = ["./src/test-setup.ts"]

[build]
# Default entrypoint (used by \`bun build\`)
# entrypoints = ["./src/index.ts"]
# Default output directory
# outdir = "./dist"
# Minify in production
# minify = true
`;
}

/**
 * Returns Bun-specific package.json scripts.
 * @param {boolean} [react=false]
 * @returns {object}
 */
function buildBunScripts(react = false) {
  return {
    dev: 'bun run --watch src/index.ts',
    start: 'bun run src/index.ts',
    build: 'bun build src/index.ts --outdir dist --target bun',
    'build:minify': 'bun build src/index.ts --outdir dist --target bun --minify',
    test: 'bun test',
    'test:watch': 'bun test --watch',
    'test:coverage': 'bun test --coverage',
    typecheck: 'tsc --noEmit',
    lint: `eslint src --ext .ts${react ? ',.tsx' : ''}`,
    'lint:fix': `eslint src --ext .ts${react ? ',.tsx' : ''} --fix`,
    format: `prettier --write "src/**/*.ts${react ? 'x' : ''}"`,
    clean: 'rm -rf dist',
    ci: 'bun run typecheck && bun test --coverage && bun run build',
  };
}

// ─── Migration steps ─────────────────────────────────────────────────────────

function getMigrationSteps() {
  return [
    {
      step: 1,
      title: 'Install Bun',
      cmd: 'curl -fsSL https://bun.sh/install | bash   # macOS/Linux\n  powershell -c "irm bun.sh/install.ps1 | iex"  # Windows',
    },
    {
      step: 2,
      title: 'Install dependencies with Bun (replaces npm install)',
      cmd: 'bun install',
    },
    {
      step: 3,
      title: 'Update tsconfig.json for Bun',
      cmd: 'node bun-workflow.js --tsconfig  (copy output to tsconfig.json)',
    },
    {
      step: 4,
      title: 'Create bunfig.toml',
      cmd: 'node bun-workflow.js --bunfig > bunfig.toml',
    },
    {
      step: 5,
      title: 'Add bun-types',
      cmd: 'bun add -D bun-types',
    },
    {
      step: 6,
      title: 'Replace npm scripts with Bun equivalents',
      cmd: 'node bun-workflow.js --scripts  (copy output to package.json)',
    },
    {
      step: 7,
      title: 'Migrate Jest tests to bun:test (optional)',
      cmd: 'Replace: import { describe, it, expect } from "@jest/globals"\nWith:    import { describe, it, expect } from "bun:test"',
    },
    {
      step: 8,
      title: 'Update CI/CD (if any)',
      cmd: 'Replace: actions/setup-node\nWith:    oven-sh/setup-bun',
    },
  ];
}

// ─── Output actions ───────────────────────────────────────────────────────────

function printHelp() {
  console.log(`
${c.bold(c.cyan('Bun TypeScript Workflow Helper'))}

${c.bold('Usage:')}
  node bun-workflow.js [option]

${c.bold('Options:')}
  --detect      Detect Bun installation and version
  --tsconfig    Print Bun-optimised tsconfig.json
  --bunfig      Print bunfig.toml template
  --scripts     Print package.json scripts for Bun projects
  --migrate     Show Node.js → Bun migration steps
  --test        Run built-in makeshift tests
  --help        Show this help
`);
}

function detectAndPrint() {
  const version = detectBun();
  if (version) {
    console.log(`\n  ${c.green('✅')}  Bun detected: ${c.bold('v' + version)}`);
    const nodeVersion = tryRun('node --version');
    if (nodeVersion) console.log(`  ${c.dim('ℹ️')}  Node.js also available: ${nodeVersion}`);
  } else {
    console.log(`\n  ${c.yellow('⚠️')}  Bun is not installed or not on PATH.`);
    console.log(`\n  Install with:`);
    console.log(`    ${c.cyan('curl -fsSL https://bun.sh/install | bash')}   # macOS/Linux`);
    console.log(`    ${c.cyan('powershell -c "irm bun.sh/install.ps1 | iex"')}  # Windows`);
  }
  console.log();
}

function printTsconfig() {
  console.log(c.bold('\n⚙️   Bun-optimised tsconfig.json (app)\n'));
  console.log(JSON.stringify(buildBunTsconfig('app'), null, 2));
  console.log(c.dim('\n  Note: module: "Preserve" + moduleResolution: "Bundler" is the recommended pair for Bun.\n'));
}

function printBunfig() {
  console.log(c.bold('\n📄  bunfig.toml template\n'));
  console.log(buildBunfig());
}

function printScripts() {
  console.log(c.bold('\n📜  package.json scripts for Bun projects\n'));
  console.log(JSON.stringify({ scripts: buildBunScripts() }, null, 2));
}

function printMigration() {
  console.log(c.bold('\n🔄  Node.js → Bun Migration Steps\n'));
  getMigrationSteps().forEach(({ step, title, cmd }) => {
    console.log(`  ${c.bold(c.cyan(step + '.'))} ${title}`);
    console.log(c.dim('     ' + cmd.replace(/\n/g, '\n     ')));
    console.log();
  });
}

// ─── Makeshift tests ─────────────────────────────────────────────────────────

function runTests() {
  console.log(c.bold('\n═══ Makeshift Tests ═══\n'));
  let passed = 0; let failed = 0;

  function assert(label, actual, expected) {
    const ok = JSON.stringify(actual) === JSON.stringify(expected);
    console.log(`  ${ok ? '\x1b[32m✅ PASS\x1b[0m' : '\x1b[31m❌ FAIL\x1b[0m'}  ${label}`);
    console.log(c.dim(`        Expected: ${JSON.stringify(expected)}`));
    if (!ok) console.log(c.dim(`        Got:      ${JSON.stringify(actual)}`));
    ok ? passed++ : failed++;
  }

  // Test 1: buildBunTsconfig sets module: Preserve
  const cfg = buildBunTsconfig('app');
  assert('buildBunTsconfig("app").compilerOptions.module', cfg.compilerOptions.module, 'Preserve');
  // Expected: 'Preserve'

  assert('buildBunTsconfig("app").compilerOptions.moduleResolution', cfg.compilerOptions.moduleResolution, 'Bundler');
  // Expected: 'Bundler'

  assert('buildBunTsconfig("app").compilerOptions.strict', cfg.compilerOptions.strict, true);
  // Expected: true

  // Test 2: buildBunTsconfig react adds jsx + DOM
  const reactCfg = buildBunTsconfig('react');
  assert('buildBunTsconfig("react") sets jsx', reactCfg.compilerOptions.jsx, 'react-jsx');
  // Expected: 'react-jsx'

  assert('buildBunTsconfig("react") includes DOM lib', reactCfg.compilerOptions.lib.includes('DOM'), true);
  // Expected: true

  assert('buildBunTsconfig("app") excludes DOM lib', cfg.compilerOptions.lib.includes('DOM'), false);
  // Expected: false

  // Test 3: buildBunfig is a non-empty string
  const bunfig = buildBunfig();
  assert('buildBunfig() returns a string', typeof bunfig, 'string');
  // Expected: 'string'

  assert('buildBunfig() contains [test] section', bunfig.includes('[test]'), true);
  // Expected: true

  assert('buildBunfig() contains [install] section', bunfig.includes('[install]'), true);
  // Expected: true

  // Test 4: buildBunfig coverage option
  const noCov = buildBunfig({ coverage: false });
  assert('buildBunfig({coverage:false}) sets coverage = false', noCov.includes('coverage = false'), true);
  // Expected: true

  // Test 5: buildBunScripts includes bun test
  const scripts = buildBunScripts();
  assert('buildBunScripts().test uses bun test', scripts.test, 'bun test');
  // Expected: 'bun test'

  assert('buildBunScripts().dev uses bun run --watch', scripts.dev.startsWith('bun run --watch'), true);
  // Expected: true

  // Test 6: getMigrationSteps returns 8 steps
  const steps = getMigrationSteps();
  assert('getMigrationSteps() returns 8 items', steps.length, 8);
  // Expected: 8

  assert('First migration step is step 1', steps[0].step, 1);
  // Expected: 1

  // Test 7: tryRun returns string for node version
  const nodeVer = tryRun('node --version');
  assert('tryRun("node --version") returns a string', typeof nodeVer, 'string');
  // Expected: 'string'

  assert('tryRun("node --version") starts with v', nodeVer.startsWith('v'), true);
  // Expected: true

  console.log(c.bold(`\n  Tests: ${c.green(passed + ' passed')}  ${failed > 0 ? '\x1b[31m' + failed + ' failed\x1b[0m' : c.dim('0 failed')}\n`));
  if (failed > 0) process.exit(1);
}

// ─── Entry point ─────────────────────────────────────────────────────────────

if (TEST)               runTests();
else if (DETECT)        detectAndPrint();
else if (SHOW_TSCONFIG) printTsconfig();
else if (SHOW_BUNFIG)   printBunfig();
else if (SHOW_SCRIPTS)  printScripts();
else if (SHOW_MIGRATE)  printMigration();
else                    printHelp();

#!/usr/bin/env node
/**
 * TypeScript Project Health Check
 *
 * Runs diagnostic checks on a TypeScript project and reports results.
 *
 * Usage:
 *   node health-check.js              # Run all checks
 *   node health-check.js --fix        # Run checks and attempt auto-fixes
 *   node health-check.js --ci         # CI mode (exit 1 on failures)
 *   node health-check.js --test       # Run built-in makeshift tests
 *
 * Dependencies (install as needed):
 *   npm install -D type-coverage knip madge @arethetypeswrong/cli size-limit
 */

import { execSync } from 'child_process';
import { existsSync, readFileSync } from 'fs';
import path from 'path';

// ─── Colour helpers ──────────────────────────────────────────────────────────
const c = {
  green:  (s) => `\x1b[32m${s}\x1b[0m`,
  red:    (s) => `\x1b[31m${s}\x1b[0m`,
  yellow: (s) => `\x1b[33m${s}\x1b[0m`,
  cyan:   (s) => `\x1b[36m${s}\x1b[0m`,
  bold:   (s) => `\x1b[1m${s}\x1b[0m`,
  dim:    (s) => `\x1b[2m${s}\x1b[0m`,
};

const PASS  = c.green('✅ PASS');
const FAIL  = c.red('❌ FAIL');
const WARN  = c.yellow('⚠️  WARN');
const SKIP  = c.dim('⏭️  SKIP');

// ─── CLI flags ───────────────────────────────────────────────────────────────
const args  = process.argv.slice(2);
const FIX   = args.includes('--fix');
const CI    = args.includes('--ci');
const TEST  = args.includes('--test');

// ─── Utilities ───────────────────────────────────────────────────────────────

/** Run a shell command and return stdout, or null on failure. */
function tryRun(cmd, opts = {}) {
  try {
    return execSync(cmd, { encoding: 'utf8', stdio: 'pipe', ...opts }).trim();
  } catch {
    return null;
  }
}

/** Check whether a CLI tool is available on PATH. */
function hasTool(name) {
  return tryRun(`${process.platform === 'win32' ? 'where' : 'which'} ${name}`) !== null;
}

/** Parse the nearest tsconfig.json and return its parsed content, or null. */
function loadTsconfig(cwd = process.cwd()) {
  const loc = path.join(cwd, 'tsconfig.json');
  if (!existsSync(loc)) return null;
  try {
    // Strip JS-style comments before parsing
    const raw = readFileSync(loc, 'utf8').replace(/\/\/[^\n]*/g, '').replace(/\/\*[\s\S]*?\*\//g, '');
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

/** Accumulate results */
const results = { pass: 0, fail: 0, warn: 0, skip: 0 };

function report(status, label, detail = '') {
  const icon = status === 'pass' ? PASS : status === 'fail' ? FAIL : status === 'warn' ? WARN : SKIP;
  results[status]++;
  console.log(`  ${icon}  ${label}${detail ? c.dim('  — ' + detail) : ''}`);
}

// ─── Check functions ─────────────────────────────────────────────────────────

function checkTsconfig() {
  console.log(c.bold('\n🔧  tsconfig.json audit'));
  const cfg = loadTsconfig();
  if (!cfg) {
    report('fail', 'tsconfig.json not found', 'run: npx tsc --init');
    return;
  }
  report('pass', 'tsconfig.json found and parseable');

  const co = (cfg.compilerOptions || {});

  const strictFlags = ['strict', 'noImplicitAny', 'strictNullChecks', 'strictFunctionTypes',
                       'strictBindCallApply', 'strictPropertyInitialization', 'noImplicitThis',
                       'alwaysStrict'];
  const enabled = strictFlags.filter(f => co[f] === true || co.strict === true);
  if (co.strict === true) {
    report('pass', 'strict: true enabled');
  } else if (enabled.length >= 4) {
    report('warn', `${enabled.length}/${strictFlags.length} strict flags enabled`, 'consider strict: true');
  } else {
    report('fail', `Only ${enabled.length}/${strictFlags.length} strict flags enabled`, 'add strict: true');
  }

  if (co.noUncheckedIndexedAccess) report('pass', 'noUncheckedIndexedAccess enabled');
  else report('warn', 'noUncheckedIndexedAccess not set', 'catches undefined array access');

  if (co.exactOptionalPropertyTypes) report('pass', 'exactOptionalPropertyTypes enabled');
  else report('warn', 'exactOptionalPropertyTypes not set');

  if (co.noImplicitOverride) report('pass', 'noImplicitOverride enabled');
  else report('warn', 'noImplicitOverride not set');
}

function checkTypeCoverage() {
  console.log(c.bold('\n📊  Type coverage'));
  if (!hasTool('type-coverage') && !existsSync('node_modules/.bin/type-coverage')) {
    report('skip', 'type-coverage not installed', 'npm install -D type-coverage');
    return;
  }
  const out = tryRun('npx type-coverage --detail');
  if (!out) { report('fail', 'type-coverage failed to run'); return; }
  const match = out.match(/(\d+\.\d+)%/);
  if (match) {
    const pct = parseFloat(match[1]);
    if (pct >= 95) report('pass', `Type coverage ${pct}%`, 'Excellent');
    else if (pct >= 80) report('warn', `Type coverage ${pct}%`, 'aim for ≥95%');
    else report('fail', `Type coverage ${pct}%`, 'high risk — many any types');
  } else {
    report('warn', 'Could not parse type-coverage output');
  }
}

function checkDeadCode() {
  console.log(c.bold('\n🧹  Dead code detection'));
  if (!hasTool('knip') && !existsSync('node_modules/.bin/knip')) {
    report('skip', 'knip not installed', 'npm install -D knip');
    return;
  }
  const out = tryRun('npx knip --reporter compact 2>&1');
  if (!out) { report('fail', 'knip failed'); return; }
  if (out.includes('No issues found')) {
    report('pass', 'No dead code / unused exports detected');
  } else {
    const lines = out.split('\n').filter(Boolean).length;
    const status = lines > 10 ? 'fail' : 'warn';
    report(status, `knip found ${lines} potential issues`, FIX ? 'review knip output above' : 'run --fix for details');
  }
}

function checkCircularDeps() {
  console.log(c.bold('\n🔄  Circular dependencies'));
  if (!hasTool('madge') && !existsSync('node_modules/.bin/madge')) {
    report('skip', 'madge not installed', 'npm install -D madge');
    return;
  }
  const src = existsSync('src') ? 'src' : '.';
  const out = tryRun(`npx madge --circular --extensions ts,tsx ${src} 2>&1`);
  if (!out) { report('warn', 'madge returned no output'); return; }
  if (out.includes('No circular dependency found') || out.trim() === '') {
    report('pass', 'No circular dependencies found');
  } else {
    report('fail', 'Circular dependencies detected', 'use shared interface files to break cycles');
    console.log(c.dim(out.split('\n').slice(0, 5).join('\n')));
  }
}

function checkDeclarationFiles() {
  console.log(c.bold('\n📦  Declaration file validation'));
  if (!hasTool('attw') && !existsSync('node_modules/.bin/attw')) {
    report('skip', '@arethetypeswrong/cli not installed', 'npm install -D @arethetypeswrong/cli');
    return;
  }
  const pkg = existsSync('package.json')
    ? JSON.parse(readFileSync('package.json', 'utf8'))
    : null;
  if (!pkg) { report('skip', 'No package.json found'); return; }

  const out = tryRun('npx attw --pack . 2>&1');
  if (!out) { report('warn', 'attw returned no output'); return; }
  if (out.includes('No problems found')) {
    report('pass', 'Declaration files look correct');
  } else {
    report('warn', 'attw found potential issues', 'review output above');
  }
}

function checkTypePerformance() {
  console.log(c.bold('\n⚡  TypeScript compile performance'));
  const out = tryRun('npx tsc --noEmit --extendedDiagnostics 2>&1');
  if (!out) { report('warn', 'tsc not available or compile errors'); return; }

  const instantiations = out.match(/Instantiations:\s+([\d,]+)/);
  const checkTime = out.match(/Check time:\s+([\d.]+)s/);

  if (instantiations) {
    const count = parseInt(instantiations[1].replace(/,/g, ''), 10);
    if (count < 1_000_000) report('pass', `Type instantiations: ${instantiations[1]}`, 'healthy');
    else if (count < 5_000_000) report('warn', `Type instantiations: ${instantiations[1]}`, 'consider simplifying complex generics');
    else report('fail', `Type instantiations: ${instantiations[1]}`, 'very slow — run tsc --generateTrace for profiling');
  }
  if (checkTime) {
    const secs = parseFloat(checkTime[1]);
    if (secs < 5) report('pass', `Check time: ${checkTime[1]}s`);
    else if (secs < 15) report('warn', `Check time: ${checkTime[1]}s`, 'consider incremental builds');
    else report('fail', `Check time: ${checkTime[1]}s`, 'enable incremental: true in tsconfig');
  }
}

// ─── Main ────────────────────────────────────────────────────────────────────

function main() {
  console.log(c.bold(c.cyan('\n╔══════════════════════════════════════╗')));
  console.log(c.bold(c.cyan('║  TypeScript Project Health Check     ║')));
  console.log(c.bold(c.cyan('╚══════════════════════════════════════╝')));
  console.log(c.dim(`  Project: ${process.cwd()}`));

  checkTsconfig();
  checkTypeCoverage();
  checkDeadCode();
  checkCircularDeps();
  checkDeclarationFiles();
  checkTypePerformance();

  // Summary
  console.log(c.bold('\n── Summary ──────────────────────────────'));
  console.log(`  ${c.green('✅')} Pass: ${results.pass}   ${c.red('❌')} Fail: ${results.fail}   ${c.yellow('⚠️')}  Warn: ${results.warn}   ${c.dim('⏭️')}  Skip: ${results.skip}`);

  if (results.fail === 0 && results.warn === 0) {
    console.log(c.green('\n  🎉  Project health is excellent!\n'));
  } else if (results.fail === 0) {
    console.log(c.yellow('\n  👍  Project is healthy with some minor warnings.\n'));
  } else {
    console.log(c.red(`\n  🚨  ${results.fail} check(s) failed. Review output above.\n`));
  }

  if (CI && results.fail > 0) process.exit(1);
}

// ─── Makeshift Tests ─────────────────────────────────────────────────────────

function runTests() {
  console.log(c.bold('\n═══ Makeshift Tests ═══\n'));
  let passed = 0;
  let failed = 0;

  function assert(label, actual, expected) {
    if (actual === expected) {
      console.log(`${PASS}  ${label}`);
      console.log(c.dim(`        Expected: ${JSON.stringify(expected)}`));
      passed++;
    } else {
      console.log(`${FAIL}  ${label}`);
      console.log(c.dim(`        Expected: ${JSON.stringify(expected)}`));
      console.log(c.dim(`        Got:      ${JSON.stringify(actual)}`));
      failed++;
    }
  }

  // Test 1: Color helpers produce ANSI codes
  const green = c.green('ok');
  assert('c.green() wraps in ANSI green', green.includes('\x1b[32m'), true);
  // Expected: true — string contains ANSI escape code

  const red = c.red('err');
  assert('c.red() wraps in ANSI red', red.includes('\x1b[31m'), true);
  // Expected: true

  // Test 2: tryRun returns null on bad command
  const bad = tryRun('this-command-does-not-exist-xyz-123 2>/dev/null');
  assert('tryRun() returns null for unknown command', bad, null);
  // Expected: null

  // Test 3: tryRun executes simple echo
  const echo = tryRun(`node -e "console.log('hello')"`);
  assert('tryRun() returns stdout of valid command', echo, 'hello');
  // Expected: 'hello'

  // Test 4: hasTool detects node
  const nodeFound = hasTool('node');
  assert('hasTool("node") returns true', nodeFound, true);
  // Expected: true (node is running this script)

  // Test 5: hasTool returns false for fake tool
  const fakeFound = hasTool('this-tool-xyz-does-not-exist-abc');
  assert('hasTool() returns false for nonexistent tool', fakeFound, false);
  // Expected: false

  // Test 6: loadTsconfig returns null when no tsconfig.json in a temp path
  const tmpCfg = loadTsconfig('/tmp');
  assert('loadTsconfig() returns null for missing tsconfig', tmpCfg, null);
  // Expected: null

  // Test 7: Results accumulator starts at 0
  const fresh = { pass: 0, fail: 0, warn: 0, skip: 0 };
  assert('results.pass initial value', fresh.pass, 0);
  // Expected: 0

  // Test 8: PASS constant includes green ANSI code
  assert('PASS constant contains green ANSI', PASS.includes('\x1b[32m'), true);
  // Expected: true

  console.log(c.bold(`\n  Tests: ${c.green(passed + ' passed')}  ${failed > 0 ? c.red(failed + ' failed') : c.dim('0 failed')}\n`));
  if (failed > 0) process.exit(1);
}

// ─── Entry point ─────────────────────────────────────────────────────────────

if (TEST) {
  runTests();
} else {
  main();
}

#!/usr/bin/env node
/**
 * TypeScript npm Workflow Helper
 *
 * Provides utilities for common TypeScript + npm project tasks:
 *   - Generate a package.json scripts block for TypeScript projects
 *   - Generate tsconfig.json templates
 *   - Print setup checklists
 *   - Audit @types packages against dependencies
 *
 * Usage:
 *   node npm-workflow.js --scripts          # Print recommended package.json scripts
 *   node npm-workflow.js --tsconfig         # Print recommended tsconfig.json
 *   node npm-workflow.js --checklist        # Print TypeScript project setup checklist
 *   node npm-workflow.js --audit-types      # Audit @types packages vs dependencies
 *   node npm-workflow.js --test             # Run built-in makeshift tests
 *
 * Self-contained — no external dependencies required.
 */

import { execSync } from 'child_process';
import { existsSync, readFileSync } from 'fs';

// ─── CLI flags ───────────────────────────────────────────────────────────────
const args        = process.argv.slice(2);
const SHOW_SCRIPTS   = args.includes('--scripts');
const SHOW_TSCONFIG  = args.includes('--tsconfig');
const SHOW_CHECKLIST = args.includes('--checklist');
const AUDIT_TYPES    = args.includes('--audit-types');
const TEST           = args.includes('--test');
const SHOW_HELP      = args.includes('--help') || args.length === 0;

// ─── Colours ─────────────────────────────────────────────────────────────────
const c = {
  green:  (s) => `\x1b[32m${s}\x1b[0m`,
  yellow: (s) => `\x1b[33m${s}\x1b[0m`,
  cyan:   (s) => `\x1b[36m${s}\x1b[0m`,
  bold:   (s) => `\x1b[1m${s}\x1b[0m`,
  dim:    (s) => `\x1b[2m${s}\x1b[0m`,
};

// ─── Templates ───────────────────────────────────────────────────────────────

/**
 * Returns recommended package.json scripts for a TypeScript project.
 * @param {object} opts
 * @param {'cjs'|'esm'} [opts.moduleType='cjs']
 * @param {boolean} [opts.includeTest=true]
 * @param {boolean} [opts.includeLint=true]
 * @returns {object} scripts map
 */
function buildScripts(opts = {}) {
  const { moduleType = 'cjs', includeTest = true, includeLint = true } = opts;
  const scripts = {
    build: 'tsc --project tsconfig.build.json',
    'build:watch': 'tsc --project tsconfig.build.json --watch',
    typecheck: 'tsc --noEmit',
    'typecheck:watch': 'tsc --noEmit --watch',
    clean: 'node -e "require(\'fs\').rmSync(\'dist\', { recursive: true, force: true })"',
    dev: 'tsx watch src/index.ts',
    start: 'node dist/index.js',
    prepare: 'npm run build',
  };

  if (includeTest) {
    Object.assign(scripts, {
      test: 'jest',
      'test:watch': 'jest --watch',
      'test:coverage': 'jest --coverage',
    });
  }

  if (includeLint) {
    Object.assign(scripts, {
      lint: 'eslint src --ext .ts,.tsx',
      'lint:fix': 'eslint src --ext .ts,.tsx --fix',
      format: 'prettier --write "src/**/*.{ts,tsx}"',
      'format:check': 'prettier --check "src/**/*.{ts,tsx}"',
    });
  }

  Object.assign(scripts, {
    validate: 'npm run typecheck && npm run lint && npm run test',
    ci: 'npm run validate && npm run build',
    prepublishOnly: 'npm run ci',
  });

  return scripts;
}

/**
 * Returns a recommended tsconfig.json for a TypeScript project.
 * @param {'node'|'react'|'lib'} [target='node']
 * @returns {object}
 */
function buildTsconfig(target = 'node') {
  const base = {
    compilerOptions: {
      target: 'ES2022',
      lib: ['ES2022'],
      module: target === 'react' ? 'ESNext' : 'CommonJS',
      moduleResolution: target === 'react' ? 'Bundler' : 'Node10',
      outDir: './dist',
      rootDir: './src',
      declaration: true,
      declarationMap: true,
      sourceMap: true,
      strict: true,
      noUncheckedIndexedAccess: true,
      exactOptionalPropertyTypes: true,
      noImplicitOverride: true,
      noImplicitReturns: true,
      noFallthroughCasesInSwitch: true,
      noUnusedLocals: true,
      noUnusedParameters: true,
      esModuleInterop: true,
      skipLibCheck: true,
      forceConsistentCasingInFileNames: true,
    },
    include: ['src'],
    exclude: ['node_modules', 'dist', '**/*.test.ts', '**/*.spec.ts'],
  };

  if (target === 'react') {
    base.compilerOptions.jsx = 'react-jsx';
    base.compilerOptions.lib = ['ES2022', 'DOM', 'DOM.Iterable'];
  }

  if (target === 'lib') {
    base.compilerOptions.declarationDir = './types';
  }

  return base;
}

/**
 * Returns the list of @types packages that are likely needed for common deps.
 * @param {string[]} deps - array of dependency names
 * @returns {string[]} recommended @types packages
 */
function suggestTypes(deps) {
  const typeMap = {
    express: '@types/express',
    node: '@types/node',
    jest: '@types/jest',
    mocha: '@types/mocha',
    chai: '@types/chai',
    react: '@types/react',
    'react-dom': '@types/react-dom',
    lodash: '@types/lodash',
    uuid: '@types/uuid',
    ws: '@types/ws',
    cors: '@types/cors',
    helmet: '@types/helmet',
    morgan: '@types/morgan',
    multer: '@types/multer',
    passport: '@types/passport',
    jsonwebtoken: '@types/jsonwebtoken',
    bcrypt: '@types/bcrypt',
    supertest: '@types/supertest',
  };

  return deps
    .filter(dep => typeMap[dep])
    .map(dep => typeMap[dep]);
}

